import pandas as pd

df = pd.read_csv('transactions.csv')
df['InvoiceDate'] = pd.to_datetime(df['InvoiceDate'])
df['year'] = df['InvoiceDate'].dt.year
df['month'] = df['InvoiceDate'].dt.month
df['line_value'] = df['Quantity'] * df['Price']

def is_non_product(row):
    stock = str(row['StockCode'])
    desc = str(row['Description']).upper()
    if stock in ['POST', 'D', 'M']:
        return True
    if desc == 'POSTAGE':
        return True
    if desc == 'CARRIAGE':
        return True
    if desc == 'MANUAL':
        return True
    if desc == 'DISCOUNT':
        return True
    if 'BANK CHARGES' in desc:
        return True
    if 'MARKETPLACE FEE' in desc:
        return True
    if 'ADJUST BAD DEBT' in desc:
        return True
    if desc.startswith('TEST'):
        return True
    if 'GIFT VOUCHER' in desc:
        return True
    if 'SAMPLE' in desc and 'SAMPLES' not in desc:
        return True
    if 'COMMISSION' in desc:
        return True
    if 'DOTCOM POSTAGE' in desc:
        return True
    if 'PADS TO MATCH' in desc:
        return True
    if 'CRUK' in desc:
        return True
    return False

df['is_non_product'] = df.apply(is_non_product, axis=1)
products = df[~df['is_non_product']].copy()

q4_2010_all = products[(products['year'] == 2010) & (products['month'].isin([10, 11, 12]))].copy()
all_cust = q4_2010_all[q4_2010_all['CustomerID'].notna()]['CustomerID'].nunique()
print(f"All customers (all countries) full Q4 2010: {all_cust}")
print(f"83 / {all_cust} = {83/all_cust*100:.1f}%")

# International full Q4 2010
intl_q4_2010 = q4_2010_all[q4_2010_all['Country'] != 'United Kingdom']
intl_cust = intl_q4_2010[intl_q4_2010['CustomerID'].notna()]['CustomerID'].nunique()
print(f"International full Q4 2010 customers: {intl_cust}")
print(f"83 / {intl_cust} = {83/intl_cust*100:.1f}%")
